\tvar cli *fasthttp.Client
\tif len(clients) != 0 {
\t\t// Set local client
\t\tcli = clients[0]
\t} else {
\t\t// Set global client
\t\tlock.RLock()
\t\tcli = client
\t\tlock.RUnlock()
